// Original version1 teaching diagrams. Keep v1 drawing semantics stable for saved work.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function egg(){return `<path d="M29 88C100 18 237 29 287 94C217 161 91 151 29 88Z" fill="#b5cf96" stroke="#3e6c48" stroke-width="3"/><path d="M36 90Q150 75 278 95M87 85l15-34m31 32l28-43m20 44l39-31m-119 33l18 46m32-47l28 57m21-55l32 44" fill="none" stroke="#709760" stroke-width="2"/><g data-life-egg="single"><path d="M159 120C151 107 151 80 164 73C178 80 179 107 170 120Z" fill="#e7c754" stroke="#8d7423" stroke-width="2"/><path d="M160 116Q157 91 164 78M168 116q7-24-2-38" fill="none" stroke="#b59932" stroke-width="1.5"/></g><text x="160" y="198" text-anchor="middle" font-size="16" fill="#183f39">Underside of a cabbage leaf</text><text x="160" y="220" text-anchor="middle" font-size="13" fill="#52675e">One enlarged egg; pictures are not to scale</text>`;}
function larva(){return `<path d="M22 173Q157 111 296 165Q201 230 22 173Z" fill="#b4cb97" stroke="#416b47" stroke-width="3"/><path d="M29 174Q156 166 285 168" fill="none" stroke="#76955c" stroke-width="2"/><path d="M64 145Q116 99 180 120T252 131" fill="none" stroke="#4f804a" stroke-width="39" stroke-linecap="round"/><path d="M64 145Q116 99 180 120T252 131" fill="none" stroke="#b6d68d" stroke-width="33" stroke-linecap="round"/>${Array.from({length:9},(_,i)=>{const u=(i+.6)/10,points=u<=.5?[[64,145],[116,99],[180,120]]:[[180,120],[244,141],[252,131]],t=u<=.5?u*2:(u-.5)*2,q=1-t,x=q*q*points[0][0]+2*q*t*points[1][0]+t*t*points[2][0],y=q*q*points[0][1]+2*q*t*points[1][1]+t*t*points[2][1],dx=2*q*(points[1][0]-points[0][0])+2*t*(points[2][0]-points[1][0]),dy=2*q*(points[1][1]-points[0][1])+2*t*(points[2][1]-points[1][1]),length=Math.hypot(dx,dy),nx=-dy/length,ny=dx/length,f=n=>n.toFixed(2);return `<path d="M${f(x-nx*14)} ${f(y-ny*14)}Q${f(x+dx/length*2)} ${f(y+dy/length*2)} ${f(x+nx*14)} ${f(y+ny*14)}" stroke="#6e9859" stroke-width="2" fill="none"/><path d="M${f(x-nx*18)} ${f(y-ny*18)}l${f(-nx*5)} ${f(-ny*5)}m${f(dx/length*5+nx*5)} ${f(dy/length*5+ny*5)}l${f(-nx*4)} ${f(-ny*4)}" stroke="#729b66" stroke-width="1.1"/>`;}).join('')}<circle cx="255" cy="131" r="16" fill="#aaca79" stroke="#4f804a" stroke-width="2"/><circle cx="262" cy="127" r="2" fill="#183f39"/><path d="M50 159L64 156Q116 110 180 131T266 145L286 167Q157 215 50 180Z" fill="#a9c789" stroke="#799e62" stroke-width="2"/><text x="160" y="222" text-anchor="middle" font-size="14" fill="#183f39">Pale green caterpillar on cabbage</text>`;}
function pupa(){return `<path d="M218 18Q209 127 222 221" fill="none" stroke="#8d7651" stroke-width="15" stroke-linecap="round"/><path d="M207 202l-9-8" fill="none" stroke="#52675e" stroke-width="3"/><path d="M197 194L164 171L145 143L134 110L150 84L156 48L171 71L190 83L194 122L207 155Z" fill="#b3c38a" stroke="#52694a" stroke-width="3"/><path d="M156 50l9 66 31 76m-59-81l31 8 26 3m-45-33l21 31-22 22m23-22l33 35m-52-10l25-1" fill="none" stroke="#789064" stroke-width="2"/><path d="M141 110Q171 100 215 105M194 122l22-17" fill="none" stroke="#c6af76" stroke-width="2.5"/><text x="160" y="246" text-anchor="middle" font-size="14" fill="#183f39">Angular chrysalis attached to a support</text>`;}
function adult(){return `<path data-life-wing="fore-left" d="M153 111C114 68 71 19 50 44C20 78 65 139 150 145Z" fill="#fffdf0" stroke="#5e6a59" stroke-width="2.5"/><path data-life-wing="fore-right" d="M167 111C206 68 249 19 270 44C300 78 255 139 170 145Z" fill="#fffdf0" stroke="#5e6a59" stroke-width="2.5"/><path data-life-wing="hind-left" d="M151 136C118 118 71 135 70 171C68 210 130 212 155 164Z" fill="#f2f1ce" stroke="#5e6a59" stroke-width="2.5"/><path data-life-wing="hind-right" d="M169 136C202 118 249 135 250 171C252 210 190 212 165 164Z" fill="#f2f1ce" stroke="#5e6a59" stroke-width="2.5"/><path d="M51 44Q33 61 39 82L66 69L76 42Q60 31 51 44ZM269 44Q287 61 281 82L254 69L244 42Q260 31 269 44Z" fill="#596057"/><g fill="#62685c"><circle cx="99" cy="103" r="6"/><circle cx="119" cy="122" r="5"/><circle cx="221" cy="103" r="6"/><circle cx="201" cy="122" r="5"/></g><path d="M158 103Q145 78 136 79M162 103q13-25 22-24" fill="none" stroke="#5a6755" stroke-width="2"/><ellipse cx="160" cy="135" rx="8" ry="38" fill="#7c8870" stroke="#4e5c48" stroke-width="2"/><circle cx="160" cy="99" r="9" fill="#7c8870"/><text x="160" y="240" text-anchor="middle" font-size="14" fill="#183f39">Adult female small white · teaching picture</text>`;}
const draw={egg,larva,pupa,adult};
export function lifeStageDiagram(stage,inline=false){const drawing=stage?.drawing;if(drawing?.version!==1||drawing.kind!==stage?.id||!Object.hasOwn(draw,drawing.kind)){const tag=inline?'span':'div',line=inline?'span':'p';return `<${tag} class="life-picture-unavailable"><strong>${esc(stage?.label||'Saved stage')}</strong> <${line}>This saved picture version is unavailable. Its original description remains:</${line}> <${line}>${esc(stage?.pictureText||'')}</${line}></${tag}>`;}const tag=inline?'span':'figure';return `<${tag} class="life-stage-diagram" data-life-drawing="${drawing.kind}" data-life-drawing-version="1"><svg viewBox="0 0 320 260" ${inline?'aria-hidden="true" focusable="false"':`role="img" aria-label="${esc(stage.pictureText)}"`}><rect x="1" y="1" width="318" height="258" rx="18" fill="#f0f4e9"/>${draw[drawing.kind]()}</svg></${tag}>`;}
